        // GET: api/trainee/{id}
        [HttpGet("{id}")]
        public async Task<IActionResult> GetById(int id)
        {
            var t = await _service.GetByIdWithDashboardDataAsync(id);
            if (t == null) return NotFound();

            var dto = new TraineeProfileDto
            {
                TraineeId = t.TraineeId,
